WHERE t.block_date >= DATE '2021-12-01'
  AND t.block_date < DATE '2022-01-08'
  AND t.block_time >= TIMESTAMP '2021-12-01 00:00:00'
  AND t.block_time < TIMESTAMP '2022-01-08 00:00:00'
